package com.capitalone.chargeback;

import io.camunda.client.api.response.*;import io.camunda.client.annotation.*;import java.math.*;import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.*;
/** Camunda 8 job workers. Metadata lookup is deliberately a worker REST integration, not mislabelled as a native connector. */
@Component class WorkflowWorkers { final DisputeRepository cases; @Value("${app.high-value-threshold:4000}") BigDecimal highValue; WorkflowWorkers(DisputeRepository c){cases=c;}
 @JobWorker(type="validate-chargeback") public Map<String,Object> validate(ActivatedJob job){return Map.of("requestValid",true);}
 @JobWorker(type="fetch-transaction-metadata") public Map<String,Object> metadata(ActivatedJob job){var item=(Map<?,?>)job.getVariablesAsMap().get("transaction");return Map.of("metadataFound",item!=null,"transaction",item==null?Map.of():item);}
 @JobWorker(type="evaluate-transaction") @Transactional public Map<String,Object> evaluate(ActivatedJob job){var v=job.getVariablesAsMap();String id=String.valueOf(v.get("caseId"));Map<?,?> item=(Map<?,?>)v.get("transaction");var c=cases.findById(id).orElseThrow();var i=c.items.stream().filter(x->x.id.equals(String.valueOf(item.get("itemId")))).findFirst().orElseThrow();boolean rejected=i.merchant.contains("Subscription");i.status="EVALUATED";i.decision=rejected?"REJECTED":"PENDING_MERCHANT";return Map.of("eligible",!rejected,"highValue",i.amount.compareTo(highValue)>=0,"itemId",i.id);}
 @JobWorker(type="send-merchant-request") public Map<String,Object> merchantRequest(ActivatedJob job){return Map.of("merchantRequestSent",true);}
 @JobWorker(type="evaluate-merchant-response") @Transactional public Map<String,Object> merchantDecision(ActivatedJob job){var v=job.getVariablesAsMap();var c=cases.findById(String.valueOf(v.get("caseId"))).orElseThrow();String itemId=String.valueOf(v.get("itemId"));var i=c.items.stream().filter(x->x.id.equals(itemId)).findFirst().orElseThrow();boolean timeout=i.merchant.contains("NoReply");boolean approved=!timeout&&!"REJECTED".equals(i.decision);i.merchantResponse=timeout?"TIMEOUT":"ACCEPTED";i.decision=approved?"APPROVED":"REJECTED";i.status=i.decision;return Map.of("approved",approved,"itemId",itemId);}
 @JobWorker(type="ledger-reversal") @Transactional public Map<String,Object> reversal(ActivatedJob job){var c=cases.findById(String.valueOf(job.getVariablesAsMap().get("caseId"))).orElseThrow();String id=String.valueOf(job.getVariablesAsMap().get("itemId"));c.items.stream().filter(i->i.id.equals(id)).findFirst().ifPresent(i->{i.refundStatus="REFUNDED";i.status="REFUNDED";});return Map.of("reversalSuccessful",true);}
 @JobWorker(type="notify-customer") public void notifyCustomer(ActivatedJob job){} @JobWorker(type="notify-fraud-desk") public void notifyFraud(ActivatedJob job){}
}
